import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md"}'),s={name:"introduction.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Arkel is a community-driven alternative to cloud object storage. Node operators contribute storage in exchange for credit, and users pay to use object storage.</p><p>Why use Arkel when alternatives like S3, R2, or B2 exist? We think there are several reasons:</p><ul><li>Cloud providers are geared towards enterprises, because that is where most of the profit is.</li><li>That results in features and incentives that benefit from massive expansion and owning the entire stack.</li><li>Arkel is a fresh take on the same problem, initially geared to supplement self-hosting use cases.</li></ul><h2 id="where-arkel-shines" tabindex="-1">Where Arkel shines <a class="header-anchor" href="#where-arkel-shines" aria-label="Permalink to &quot;Where Arkel shines&quot;">​</a></h2><ul><li>Easy remote backups for your self-hosting servers.</li><li>Media offload services — think Immich, Mastodon media, forum attachments.</li><li>Avoiding vendor dependence: not just major outages, but surprise or hidden charges and unethical practices.</li><li>A second life for old storage hardware that is not being used.</li><li>Community and friends helping each other out.</li></ul><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ul><li><strong>Client-side encryption</strong> — objects are encrypted on your machine before upload (<code>chacha20poly1305</code>), so storage nodes only ever hold ciphertext.</li><li><strong>Erasure coding</strong> — the ciphertext is split into <code>k</code> data shards and <code>m</code> parity shards, spread across independent storage nodes. The network survives losing up to <code>m</code> nodes.</li><li><strong>Distributed metadata</strong> — a Raft cluster of index nodes owns the global metadata: buckets, objects, ownership, and quotas. No single company controls the index.</li><li><strong>An economy</strong> — accounts hold quota, storage operators earn contribution grants, and a payment operator credits accounts.</li></ul><h2 id="project-status" tabindex="-1">Project status <a class="header-anchor" href="#project-status" aria-label="Permalink to &quot;Project status&quot;">​</a></h2><p>The project is in early alpha, with contribution and usage possible. The main instance of the network is scheduled to go live soon. See the <a href="/roadmap">roadmap</a> for where things are heading.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/quickstart">Quick start</a> — build, run a node, and store your first object.</li><li><a href="/contribute">Contribute</a> — run a storage node and earn quota.</li><li><a href="/cli">CLI reference</a> — the full command surface.</li></ul>',12)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
